from collections import deque

start_node = "3435c378bb"
visited = {start_node: 0}
queue = deque([start_node])

while queue:
    current = queue.popleft()
    current_depth = visited[current]

    if current_depth >= 2:  # Don't go beyond depth 2
        continue

    if current in graph:
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited[neighbor] = current_depth + 1
                queue.append(neighbor)

# Get nodes at exactly depth 2
depth_1_nodes = sorted([node for node, depth in visited.items() if depth == 1])
depth_2_nodes = sorted([node for node, depth in visited.items() if depth == 2])

